import os, re, html, subprocess, requests, sys
from html.parser import HTMLParser

URLS = {
    "Do Things that Don't Scale": "https://www.paulgraham.com/ds.html",
    "Founder Mode": "https://www.paulgraham.com/foundermode.html",
}

class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.texts = []
    def handle_data(self, data):
        if data.strip():
            self.texts.append(data.strip())

def fetch_text(url: str) -> str:
    html_content = subprocess.check_output(['curl', '-s', url], text=True)
    html_content = re.sub(r'<script[^>]*>.*?</script>', '', html_content, flags=re.DOTALL|re.IGNORECASE)
    html_content = re.sub(r'<style[^>]*>.*?</style>', '', html_content, flags=re.DOTALL|re.IGNORECASE)
    parser = TextExtractor()
    parser.feed(html_content)
    text = ' '.join(parser.texts)
    text = html.unescape(text)
    text = re.sub(r'\s+', ' ', text)
    return text

def extract_essay(text: str, start_marker: str, end_marker: str = "Thanks to") -> str:
    start = text.find(start_marker)
    if start == -1:
        start = 0
    end = text.find(end_marker, start)
    if end != -1:
        end_sentence = text.find('.', end)
        if end_sentence != -1:
            end = end_sentence + 1
        else:
            end = end + len(end_marker)
        text = text[start:end]
    else:
        text = text[start:]
    return text

def clean_text(text: str) -> str:
    text = re.sub(r'\[\s*\d+\s*\]', '', text)
    text = re.sub(r'\s+', ' ', text)
    return text.strip()

def chunk_text(text: str, max_chars: int = 3000):
    sentences = re.split(r'(?<=[.!?])\s+', text)
    chunks = []
    current = ""
    for sentence in sentences:
        if len(current) + len(sentence) + 1 <= max_chars:
            current += sentence + " "
        else:
            if current:
                chunks.append(current.strip())
            current = sentence + " "
    if current:
        chunks.append(current.strip())
    return chunks

def main():
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        print("OPENAI_API_KEY not set", file=sys.stderr)
        sys.exit(1)

    combined = []
    for title, url in URLS.items():
        raw_text = fetch_text(url)
        start_marker = "July 2013" if "Don't Scale" in title else "September 2024"
        essay_text = extract_essay(raw_text, start_marker)
        essay_text = clean_text(essay_text)
        combined.append(f"{title} by Paul Graham. {essay_text}")

    full_text = "\n\n".join(combined)
    full_text = clean_text(full_text)

    chunks = chunk_text(full_text, max_chars=3000)
    print(f"Total chunks: {len(chunks)}")

    out_dir = "/tmp/tts_chunks"
    os.makedirs(out_dir, exist_ok=True)
    chunk_files = []

    for i, chunk in enumerate(chunks, 1):
        print(f"Generating chunk {i}/{len(chunks)} (chars: {len(chunk)})")
        resp = requests.post(
            "https://api.openai.com/v1/audio/speech",
            headers={"Authorization": f"Bearer {api_key}"},
            json={"model": "gpt-4o-mini-tts", "voice": "alloy", "input": chunk}
        )
        if resp.status_code != 200:
            print("Error from OpenAI:", resp.status_code, resp.text, file=sys.stderr)
            sys.exit(1)
        chunk_path = os.path.join(out_dir, f"chunk_{i:03d}.mp3")
        with open(chunk_path, "wb") as f:
            f.write(resp.content)
        chunk_files.append(chunk_path)

    # Create concat list for ffmpeg
    list_path = os.path.join(out_dir, "concat_list.txt")
    with open(list_path, "w") as f:
        for path in chunk_files:
            f.write(f"file '{path}'\n")

    output_path = "/root/audiobook.mp3"
    subprocess.check_call(["ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", list_path, "-c", "copy", output_path])
    print(f"Saved audiobook to {output_path}")

if __name__ == "__main__":
    main()
